color.colorFunction:
// Function takes `data` mapping the current entity's keys
let score = data['health_score'];

// If the key is missing (loading), default to blue
if (score === undefined || score === null) {
    return '#2196f3';
}

if (score < 40) {
    return '#ff0000'; // Critical Health (Red)
} else if (score < 75) {
    return '#ffa500'; // Warning Health (Orange)
} else {
    return '#00ff00'; // Optimal Health (Green)
}

markerClustering.clusterMarkerColorFunction:
let total = 0;
let count = 0;

for (let markerData of data) {
    let score = Number(markerData.device.health.score);

    if (!isNaN(score)) {
        total += score;
        count++;
    }
}

// No valid score found in cluster
if (count === 0) {
    return '#2196f3';
}

let avgScore = total / count;

if (avgScore < 40) {
    return '#ff0000';   // Critical Health
} else if (avgScore < 75) {
    return '#ffa500';   // Warning Health
} else {
    return '#00ff00';   // Optimal Health
}

valueColor.colorFunction:
